21	func ParseFormat(raw string) (CheckpointFormat, error) {
22		familyRaw, majorRaw, ok := strings.Cut(raw, "-v")
23		if !ok || familyRaw == "" || majorRaw == "" {
24			return CheckpointFormat{}, fmt.Errorf("invalid checkpoint format %q", raw)
25		}
26	
27		family := CheckpointFamily(familyRaw)
28		if _, ok := knownFamilies[family]; !ok {
29			return CheckpointFormat{}, fmt.Errorf("unknown checkpoint family %q", familyRaw)
30		}
31	
32		major, err := strconv.Atoi(majorRaw)
33		if err != nil || major <= 0 {
34			return CheckpointFormat{}, fmt.Errorf("invalid checkpoint major %q", majorRaw)
35		}
36	
37		return CheckpointFormat{Family: family, Major: major}, nil
38	}
